def stem(w):
    """Crude suffix strip so 'scanned' meets 'scan' and 'pages' meets 'page'."""
    for suf in ("ing", "ed", "s"):
        if len(w) - len(suf) >= 3 and w.endswith(suf) and not w.endswith("ss"):
            w = w[: -len(suf)]
            break
