def about_hits(db, path, q):
    """Question words in what the file says it is about: its name plus a frontmatter title/description line.
    Memory names are topic slugs and their description is a one-line summary; articles carry a title."""
    about = os.path.basename(path)[:-3].replace("_", " ").replace("-", " ")
    row = db.execute("SELECT body FROM d WHERE path = ?", (path,)).fetchone()
    if row:
        head = row[0].split("\n")[:40]  # body starts with the name line, then the frontmatter
        if len(head) > 1 and head[1].strip() == "---":
            for line in head[2:]:
                if line.strip() == "---":
                    break
                if line.startswith(("title:", "description:")):
